#include "pristine_dispatch_factories.h"
#include "pristine_creation_identities.h"
#include "include/cef_api_hash.h"
#include <cassert>
#include <cstdio>
#include <deque>
#include <set>
#include <map>
using Factory=suitecut::PristineDispatchFactories;
using Dict=Factory::Dict;
struct Backend{
  struct Command{Factory::Context context;std::string method;Dict params;double deadline;Factory::Reply reply;};
  double now=100;std::set<std::string>live{"one","two"};std::deque<Command>commands;int closes=0,replies=0;bool ok=false,refuse=false;std::string error;std::unique_ptr<Factory>factory;std::map<std::string,Factory::Ticket>tickets;
  Backend(){factory=std::make_unique<Factory>(Factory::Hooks{[this]{return now;},[this](const auto&c){return live.contains(c.identity);},[this](const auto&c,const auto&m,Dict p,double d,auto r){if(refuse)return false;commands.push_back({c,m,p->Copy(false),d,std::move(r)});return true;},[this](const auto&,const auto&){++closes;},[]{}});}
  Factory::Context Owner(std::string identity="one",int context=7){return {"","frame","loader",std::move(identity),context,1,1};}
  void Start(Factory::Context c,double d=500){auto&ticket=tickets[c.identity];if(!ticket)ticket=factory->Expect(c,Factory::Barrier::NewDocumentBootstrap,d);factory->Capture(ticket,[this](bool success,auto value,const auto&e){++replies;ok=success;error=e;if(success)assert(value&&!value->object.empty());});}
  void Ack(bool success=true,Dict result=nullptr){assert(!commands.empty());auto c=std::move(commands.front());commands.pop_front();if(!result){result=CefDictionaryValue::Create();if(c.method=="Runtime.evaluate"){auto remote=CefDictionaryValue::Create();remote->SetString("type","function");remote->SetString("objectId","real-protocol-object-"+c.context.identity);result->SetDictionary("result",remote);}}c.reply(success,result,success?"":"real protocol failure");}
  void Clean(){factory->ContextsCleared("","document changed");while(!commands.empty())Ack();assert(factory->PhysicalCount()==0);auto d=CefDictionaryValue::Create();factory->Diagnostics(d);assert(d->GetInt("pristineDispatchGroups")==0);factory->Closed();}
};
int main(){assert(cef_api_hash(CEF_API_VERSION,0));int groups=0;
 {suitecut::PristineCreationIdentities ids;using Result=suitecut::PristineCreationIdentities::Observation;assert(ids.Observe(1,"actual-one")==Result::Fresh);assert(ids.Observe(1,"actual-one")==Result::Known);assert(ids.Count()==1);++groups;}
 {suitecut::PristineCreationIdentities ids;using Result=suitecut::PristineCreationIdentities::Observation;assert(ids.Observe(1,"actual-one")==Result::Fresh);/* Logical context loss deliberately does not call Destroyed. */assert(ids.Observe(1,"actual-one")==Result::Known);assert(ids.Observe(2,"actual-one")==Result::Fresh);ids.SessionClosed(1);assert(ids.Count()==1);assert(ids.Observe(2,"actual-one")==Result::Known);++groups;}
 {suitecut::PristineCreationIdentities ids;using Result=suitecut::PristineCreationIdentities::Observation;for(size_t i=0;i<4096;++i)assert(ids.Observe(1,"real-"+std::to_string(i))==Result::Fresh);assert(ids.Observe(1,"overflow")==Result::Capacity);assert(ids.Observe(1,"real-0")==Result::Known);ids.Destroyed(1,"real-0");assert(ids.Observe(1,"new-realm")==Result::Fresh);assert(ids.Count()==4096);++groups;}
 {suitecut::PristineCreationIdentities ids;using Result=suitecut::PristineCreationIdentities::Observation;assert(ids.Observe(0,"one")==Result::Capacity);assert(ids.Observe(1,"")==Result::Capacity);assert(ids.Observe(1,std::string(257,'x'))==Result::Capacity);assert(ids.Count()==0);++groups;}
 {suitecut::PristineCreationIdentities ids;using Result=suitecut::PristineCreationIdentities::Observation;assert(ids.Observe(1,"one")==Result::Fresh);ids.Destroyed(2,"one");assert(ids.Observe(1,"one")==Result::Known);ids.Closed();assert(ids.Count()==0);assert(ids.Observe(1,"one")==Result::Fresh);++groups;}

 {Backend b;b.Start(b.Owner());assert(b.replies==0&&b.factory->PhysicalCount()==1);assert(b.commands.front().params->GetString("expression").ToString().find("globalThis.Reflect.apply")!=std::string::npos);assert(b.commands.front().params->GetBool("disableBreaks"));assert(b.commands.front().params->GetString("uniqueContextId")=="one"&&!b.commands.front().params->HasKey("contextId"));b.Ack();assert(b.ok&&b.factory->Find(b.Owner()));b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.Start(b.Owner());assert(b.commands.size()==1);b.Ack();assert(b.replies==2&&b.ok);b.Start(b.Owner());assert(b.replies==3&&b.commands.empty());b.Clean();++groups;}
 {Backend b;b.Start(b.Owner(),100);assert(b.replies==1&&!b.ok&&b.commands.empty());b.Start(b.Owner(),110);b.now=111;b.Ack();assert(b.replies==2&&!b.ok&&!b.factory->Find(b.Owner()));assert(b.commands.front().method=="Runtime.releaseObjectGroup"&&b.factory->PhysicalCount()==1);b.Ack();b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.factory->Invalidate(b.Owner(),"caller original reason");assert(b.replies==1&&b.error=="caller original reason"&&b.factory->PhysicalCount()==1);assert(b.commands.size()==1);b.Ack();assert(b.commands.size()==1&&b.commands.front().method=="Runtime.releaseObjectGroup");b.Ack();assert(b.replies==1);b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.Ack();b.factory->ContextsCleared("","actual executionContextsCleared");assert(!b.factory->Find(b.Owner())&&b.factory->PhysicalCount()==1);b.Ack();b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.factory->Invalidate(b.Owner(),"old context retired");b.Start(b.Owner("two"));assert(b.commands.size()==2);b.Ack();assert(!b.factory->Find(b.Owner())&&!b.factory->Find(b.Owner("two")));b.Ack();assert(b.factory->Find(b.Owner("two")));b.Ack();b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.Ack();b.factory->Invalidate(b.Owner(),"retired");b.Ack(false);assert(b.closes==1&&b.factory->PhysicalCount()==0);auto d=CefDictionaryValue::Create();b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchGroups")==1);b.factory->SessionClosed("");b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchGroups")==0);++groups;}
 {Backend b;for(int i=0;i<64;++i){const auto name="owner-"+std::to_string(i);b.live.insert(name);b.Start(b.Owner(name,1+i));}b.Start(b.Owner("two"));assert(b.replies==1&&!b.ok&&b.factory->PhysicalCount()==64&&b.commands.size()==64);b.factory->ContextsCleared("","actual clear");assert(b.replies==65&&b.factory->PhysicalCount()==64);while(!b.commands.empty())b.Ack();b.Clean();++groups;}
 {Backend b;b.Start(b.Owner(),110);b.now=111;b.factory->Tick(b.now);assert(b.replies==1&&!b.ok&&b.factory->PhysicalCount()==1);b.factory->Tick(1000);assert(b.replies==1);b.Ack();assert(b.factory->PhysicalCount()==1);b.Ack();b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());auto callback=b.commands.front().reply;b.factory->SessionClosed("");assert(b.replies==1&&!b.ok&&b.factory->PhysicalCount()==0);callback(true,CefDictionaryValue::Create(),"");assert(b.replies==1&&b.commands.size()==1);b.commands.clear();b.Clean();++groups;}
 {Backend b;b.Start(b.Owner(),110);b.now=111;b.factory->Tick(b.now);assert(b.replies==1&&b.factory->PhysicalCount()==1);b.factory->Tick(30110);assert(b.closes==1&&b.factory->PhysicalCount()==1);b.factory->Tick(50000);assert(b.closes==1&&b.factory->PhysicalCount()==1&&!b.factory->NeedsTick());b.factory->SessionClosed("");assert(b.factory->PhysicalCount()==0);b.commands.clear();b.Clean();++groups;}
 {Backend b;for(int i=0;i<64;++i)b.Start(b.Owner());assert(b.commands.size()==1&&b.replies==0);b.Start(b.Owner("two"));assert(b.replies==1&&!b.ok&&b.commands.size()==1);b.Ack();assert(b.replies==65&&b.ok);b.Clean();++groups;}
 {Backend b;int failures=0;b.factory->Capture(0,[&](bool ok,auto,const auto&){assert(!ok);++failures;});assert(failures==1&&b.commands.empty());auto ticket=b.factory->Expect(b.Owner(),Factory::Barrier::InitialSettingsHold,110);assert(ticket);assert(!b.factory->Expect(b.Owner(),Factory::Barrier::NewDocumentBootstrap,500));b.factory->Capture(ticket,[&](bool ok,auto,const auto&){assert(!ok);++failures;});b.now=111;b.factory->Tick(b.now);assert(failures==2);b.Ack();b.Ack();assert(!b.factory->Expect(b.Owner(),Factory::Barrier::NewDocumentBootstrap,500));b.factory->Capture(ticket,[&](bool ok,auto,const auto&){assert(!ok);++failures;});assert(failures==3&&b.commands.empty());b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.Ack(false);b.Ack();assert(!b.factory->Expect(b.Owner(),Factory::Barrier::NewDocumentBootstrap,500));b.Start(b.Owner());assert(b.replies==2&&!b.ok&&b.commands.empty());b.Clean();++groups;}
 {Backend b;const auto ticket=b.factory->Expect(b.Owner(),Factory::Barrier::InitialSettingsHold,110);int good=0,bad=0;b.factory->Capture(ticket,[&](bool ok,auto,const auto&){assert(ok);++good;});b.Ack();b.now=110;b.factory->Capture(ticket,[&](bool ok,auto,const auto&e){assert(!ok&&e.find("deadline")!=std::string::npos);++bad;});assert(good==1&&bad==1&&b.factory->Find(b.Owner()));b.Clean();++groups;}
 {Backend b;assert(b.factory->Expect(b.Owner(),Factory::Barrier::NewDocumentBootstrap,500));auto d=CefDictionaryValue::Create();b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchBootstrapTickets")==1);b.factory->Closed();b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchBootstrapTickets")==0&&d->GetInt("pristineDispatchGroups")==0&&b.factory->PhysicalCount()==0);++groups;}
 {Backend b;const auto ticket=b.factory->Expect(b.Owner(),Factory::Barrier::NewDocumentBootstrap,500);b.factory->Invalidate(b.Owner(),"Native creation provenance retired");int failed=0;b.factory->Capture(ticket,[&](bool ok,auto,const auto&){assert(!ok);++failed;});assert(failed==1&&b.commands.empty()&&!b.factory->Expect(b.Owner(),Factory::Barrier::NewDocumentBootstrap,500));b.Clean();++groups;}
 {Backend b;b.refuse=true;b.Start(b.Owner());assert(b.replies==1&&!b.ok&&b.commands.empty()&&b.closes==0&&b.factory->PhysicalCount()==0);auto d=CefDictionaryValue::Create();b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchGroups")==0);b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.Ack();b.factory->RealmDestroyed("",1,"actual renderer death");auto d=CefDictionaryValue::Create();b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchGroups")==0&&b.factory->PhysicalCount()==0&&b.commands.empty()&&!b.factory->Find(b.Owner())&&b.closes==0);b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.factory->RealmDestroyed("",1,"actual renderer death");assert(b.replies==1&&!b.ok&&b.error=="actual renderer death"&&b.factory->PhysicalCount()==1&&b.commands.size()==1);b.Ack();assert(b.factory->PhysicalCount()==0&&b.commands.empty()&&b.closes==0&&!b.factory->Find(b.Owner()));b.Clean();++groups;}
 {Backend b;b.Start(b.Owner());b.Ack();b.factory->ContextsCleared("","logical clear before process notification");assert(b.factory->PhysicalCount()==1);b.factory->RealmDestroyed("",1,"actual renderer death");assert(b.factory->PhysicalCount()==1);auto d=CefDictionaryValue::Create();b.factory->Diagnostics(d);assert(d->GetInt("pristineDispatchGroups")==0);b.Ack(false);assert(b.factory->PhysicalCount()==0&&b.closes==0);b.Clean();++groups;}
 {Backend b;auto child=b.Owner("two");child.session="surviving-oopif";b.Start(b.Owner());b.Ack();b.Start(child);b.Ack();b.factory->RealmDestroyed("",1,"actual main renderer death");assert(!b.factory->Find(b.Owner())&&b.factory->Find(child)&&b.commands.empty());b.factory->ContextsCleared(child.session,"actual child context retired");assert(b.commands.size()==1);b.Ack();b.Clean();++groups;}
 {Backend b;auto next=b.Owner("two");next.source_epoch=2;b.Start(b.Owner());b.Ack();b.Start(next);b.Ack();b.factory->RealmDestroyed("",1,"actual old renderer death");assert(!b.factory->Find(b.Owner())&&b.factory->Find(next));b.Clean();++groups;}
 {Backend b;b.Start(b.Owner(),110);b.factory->RealmDestroyed("",1,"actual renderer death");assert(b.factory->PhysicalCount()==1&&b.factory->NeedsTick());b.factory->Tick(30110);assert(b.factory->PhysicalCount()==1&&b.closes==1&&!b.factory->NeedsTick());b.Ack(false);assert(b.factory->PhysicalCount()==0&&b.closes==1&&b.commands.empty());b.Clean();++groups;}
 std::printf("PristineDispatchFactories: %d controlled groups PASS\n",groups);
}
